async void Import_Click(object s, RoutedEventArgs e)
{
    var progress = new Progress<int>(p => bar.Value = p); // created on the UI thread
    await Task.Run(() => Import(files, progress));
    status.Text = "done";
}

void Import(string[] files, IProgress<int> p)              // knows nothing about the window
{
    for (int i = 0; i < files.Length; i++)
    {
        ImportFile(files[i]);
        p.Report((i + 1) * 100 / files.Length);             // Post to the UI context
    }
}

