async void Build_Click(object s, RoutedEventArgs e)
{
    var points = await LoadPointsAsync();                // wait without a thread
    var mesh = await Task.Run(() => BuildMesh(points));  // 3 s of computing, on the pool
    viewport.Show(mesh);                                 // back on the UI thread
}

